from abc import ABC, abstractmethod

# Abstract class for sorting algorithms
class SortAlgorithm(ABC):
    def __init__(self):
        pass

    # Template method for sorting algorithm skeleton
    @abstractmethod
    def sort(self, array):
        pass

    # Abstract method for comparing elements
    @abstractmethod
    def compare(self, element1, element2):
        pass

    # Abstract method for swapping elements
    @abstractmethod
    def swap(self, element1, element2):
        pass


# Concrete subclass for Bubble Sort
class BubbleSort(SortAlgorithm):
    def sort(self, array):
        n = len(array)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(array[j], array[j + 1]) > 1:
                    self.swap(array[j], array[j + 1])
        return array

    def compare(self, element1, element2):
        return element1 - element2

    def swap(self, element1, element2):
        temp = element1
        element1 = element2
        element2 = temp


# Concrete subclass for Selection Sort
class SelectionSort(SortAlgorithm):
    def sort(self, array):
        n = len(array)
        for i in range(n):
            min_index = i
            for j in range(i + 1, n):
                if self.compare(array[j], array[min_index]) < 1:
                    min_index = j
            self.swap(array[i], array[min_index])
        return array

    def compare(self, element1, element2):
        return element1 - element2

    def swap(self, element1, element2):
        temp = element1
        element1 = element2
        element2 = temp


# Test the implementation
if __name__ == "__main__":
    # Create instances of different sorting algorithm classes
    bubble_sort = BubbleSort()
    selection_sort = SelectionSort()

    # Create arrays of integers and strings
    array_integers = [64, 34, 25, 12, 22, 11, 90]
    array_strings = ["dog", "cat", "apple", "banana", "elephant", "bird", "car"]

    # Sort the arrays using each algorithm
    print("Sorted array using Bubble Sort:", bubble_sort.sort(array_integers))
    print("Sorted array using Selection Sort:", selection_sort.sort(array_integers))
    print("Sorted array using Bubble Sort:", bubble_sort.sort(array_strings))
    print("Sorted array using Selection Sort:", selection_sort.sort(array_strings))
